effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN: the source is always fetched through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

// Three positions only, so the cycle always returns home after three steps.
vec3 rot3(vec3 c, float n){
float k = mod(floor(n), 3.0);
if (k < 0.5) return c;
if (k < 1.5) return vec3(c.g, c.b, c.r);
return vec3(c.b, c.r, c.g);
}

// m=0 none, 1 R<->G, 2 G<->B, 3 R<->B, 4 full cycle.
vec3 swapPairs(vec3 c, float m){
if (m < 0.5) return c;
if (m < 1.5) return vec3(c.g, c.r, c.b);
if (m < 2.5) return vec3(c.r, c.b, c.g);
if (m < 3.5) return vec3(c.b, c.g, c.r);
return vec3(c.b, c.r, c.g);
}

// A 3-bit mask beats three separate switches: one control flips any subset.
vec3 invertBits(float m){
float r = mod(floor(m), 2.0);
float g = mod(floor(m / 2.0), 2.0);
float b = mod(floor(m / 4.0), 2.0);
return vec3(r, g, b);
}

// Luma Split needs a real CHROMA rotation, not a channel permutation: permuting
// is linear, so rotating the whole colour and rotating only its chroma give the
// same answer. Going through YCbCr and spinning the (Cb,Cr) pair is the only way
// to hold the luminance exactly while the colour balance turns.
vec3 rgb2ycc(vec3 c){
return vec3(dot(c, vec3(0.299, 0.587, 0.114)),
dot(c, vec3(-0.168736, -0.331264, 0.5)) + 0.5,
dot(c, vec3(0.5, -0.418688, -0.081312)) + 0.5);
}
vec3 ycc2rgb(vec3 v){
float y  = v.x;
float cb = v.y - 0.5;
float cr = v.z - 0.5;
return vec3(y + 1.402 * cr,
y - 0.344136 * cb - 0.714136 * cr,
y + 1.772 * cb);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

// Un-premultiply for the colour work, re-premultiply at the end.
float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

vec3 c = sat3v(sc * gain);

vec3 v = c;
if (swapMode <= 0){
v = rot3(c, rotateSteps);
} else if (swapMode <= 1){
// The mixer rows are read straight from the params, so this one branch can
// express a plain swap, a mono conversion, a cross-process or a full invert.
v = vec3(dot(c, vec3(mixRR, mixRG, mixRB)),
         dot(c, vec3(mixGR, mixGG, mixGB)),
         dot(c, vec3(mixBR, mixBG, mixBB)));
} else if (swapMode <= 2){
v = c;
} else if (swapMode <= 3){
v = swapPairs(c, pairMode);
} else {
// Luma Split - spin the chroma pair around a fixed luma, 120 degrees per step,
// so the picture keeps its brightness and only the colour balance turns.
vec3  ycc = rgb2ycc(c);
float ang = rotateSteps * 2.0943951;
float ca  = cos(ang);
float sa  = sin(ang);
vec2  q   = vec2(ycc.y - 0.5, ycc.z - 0.5);
q = vec2(q.x * ca - q.y * sa, q.x * sa + q.y * ca);
v = sat3v(ycc2rgb(vec3(ycc.x, q.x + 0.5, q.y + 0.5)));
}

// Invert mask last, so it also applies to the mixer and the pair swaps.
v = mix(v, vec3(1.0) - v, invertBits(invertMask));

float l2 = lum(v);
v = sat3v(mix(vec3(l2), v, max(saturation, 0.0)));

vec3  col = mix(sc, v, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
